  this.abh = "Sprawdzamy w\u0119ze\u0142";
  this.abi = "Ka\u017cdy zapis i podpis Twojego konta, od pierwszego.";
  this.abg = "W\u0119ze\u0142 sprawdzony";
  this.aaB = "\u0141a\u0144cuch wymienia klucz innego w\u0119z\u0142a.";
