  this.adi = "W\u0119ze\u0142 nie poda\u0142 dowodu dla tego konta.";
  this.aca = "Podsumowanie w\u0119z\u0142a nie jest podpisane jego kluczem.";
  this.adK = "Tw\u00f3j \u0142a\u0144cuch nie wchodzi w podpisane podsumowanie w\u0119z\u0142a.";
  this.abJ = "To urz\u0105dzenie policzy\u0142o wszystko samo; w\u0119ze\u0142 zosta\u0142 poproszony tylko o zapisy.";
  this.acQ = "Uczestnicy";
  this.afl = "Suma sald";
  this.afm = "Suma wszystkich sald zawsze wynosi zero: jednostka powstaje, gdy uczestnik kupuje, i znika, gdy sprzedaje.";
  this.acP = "Uczestnik";
  this.abF = "Linia kredytowa";
