  this.ajc = "\u0412 \u0442\u043e\u0439 \u043e\u0431\u0449\u0438\u043d\u0435 \u043f\u043e\u043a\u0430 \u043d\u0435\u043a\u043e\u043c\u0443 \u043f\u043b\u0430\u0442\u0438\u0442\u044c.";
  this.alp = "\u041b\u0438\u043d\u0438\u0438 \u0434\u043e\u0432\u0435\u0440\u0438\u044f";
  this.aiv = "\u041b\u0438\u043d\u0438\u044f \u0434\u043e\u0432\u0435\u0440\u0438\u044f \u0433\u043e\u0432\u043e\u0440\u0438\u0442, \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0434\u0440\u0443\u0433\u0430\u044f \u043e\u0431\u0449\u0438\u043d\u0430 \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u0434\u043e\u043b\u0436\u043d\u0430 \u043d\u0430\u0448\u0435\u0439. \u0422\u043e\u0433\u0434\u0430 \u0435\u0451 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0438 \u043c\u043e\u0433\u0443\u0442 \u043f\u043b\u0430\u0442\u0438\u0442\u044c \u043d\u0430\u0448\u0438\u043c, \u0430 \u043d\u0430\u0448\u0438 \u2014 \u0435\u0451 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0430\u043c, \u043d\u0430\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u041e\u041d\u0410 \u0434\u043e\u0432\u0435\u0440\u044f\u0435\u0442 \u043d\u0430\u043c. \u041f\u043b\u044e\u0441 \u043d\u0430 \u0431\u0430\u043b\u0430\u043d\u0441\u0435: \u0434\u043e\u043b\u0436\u043d\u044b \u043c\u044b; \u043c\u0438\u043d\u0443\u0441: \u0434\u043e\u043b\u0436\u043d\u044b \u043d\u0430\u043c.";
  this.alj = "\u041c\u043e\u0433\u0443\u0442 \u0431\u044b\u0442\u044c \u0434\u043e\u043b\u0436\u043d\u044b \u043d\u0430\u043c";
  this.aj4 = "\u043b\u0438\u043d\u0438\u0439 \u043f\u043e\u043a\u0430 \u043d\u0435\u0442";
  this.ajQ = "\u041e\u0442\u043a\u0440\u044b\u0442\u044c \u043b\u0438\u043d\u0438\u044e";
  this.aip = "\u0410\u0434\u0440\u0435\u0441 \u0434\u0440\u0443\u0433\u043e\u0439 \u043e\u0431\u0449\u0438\u043d\u044b";
  this.aiq = "\u043a\u0430\u043a \u0432 \u0435\u0451 \u0441\u0441\u044b\u043b\u043a\u0435-\u043f\u0440\u0438\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0438 \u043f\u043e\u0441\u043b\u0435 ?node=";
  this.ah0 = "\u0418\u0437\u043c\u0435\u043d\u0438\u0442\u044c";
  this.ais = "\u041b\u0438\u043d\u0438\u044f \u043e\u0442\u043a\u0440\u044b\u0442\u0430";
  this.air = "\u041b\u0438\u043d\u0438\u044f \u043d\u0435 \u043e\u0442\u043a\u0440\u044b\u0442\u0430";
  this.aiu = "\u0422\u0430 \u043e\u0431\u0449\u0438\u043d\u0430 \u0441\u0447\u0438\u0442\u0430\u0435\u0442 \u0432 \u0434\u0440\u0443\u0433\u043e\u0439 \u0435\u0434\u0438\u043d\u0438\u0446\u0435: \u043b\u0438\u043d\u0438\u0438 \u043c\u0435\u0436\u0434\u0443 \u0440\u0430\u0437\u043d\u044b\u043c\u0438 \u0435\u0434\u0438\u043d\u0438\u0446\u0430\u043c\u0438 \u0435\u0449\u0451 \u043d\u0435 \u0441\u0434\u0435\u043b\u0430\u043d\u044b.";
  this.ajb = "\u041f\u043e \u044d\u0442\u043e\u043c\u0443 \u0430\u0434\u0440\u0435\u0441\u0443 \u043e\u0431\u0449\u0438\u043d\u0430 \u043d\u0435 \u043e\u0442\u0432\u0435\u0447\u0430\u0435\u0442.";
  this.ait = "\u042d\u0442\u043e \u0441\u0430\u043c\u0430 \u043d\u0430\u0448\u0430 \u043e\u0431\u0449\u0438\u043d\u0430.";
  this.alI = "\u041a\u0442\u043e \u043c\u043e\u0436\u0435\u0442 \u0432\u0441\u0442\u0443\u043f\u0438\u0442\u044c";
  this.agL = "\u0442\u043e\u043b\u044c\u043a\u043e \u0431\u0438\u0437\u043d\u0435\u0441\u044b \u0438 \u0441\u0430\u043c\u043e\u0437\u0430\u043d\u044f\u0442\u044b\u0435 (\u043f\u0440\u043e\u0449\u0435 \u0432\u0441\u0435\u0433\u043e)";
  this.ak1 = "\u0431\u0438\u0437\u043d\u0435\u0441\u044b \u0438 \u0447\u0430\u0441\u0442\u043d\u044b\u0435 \u043b\u0438\u0446\u0430, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0441\u043d\u0430\u0447\u0430\u043b\u0430 \u0437\u0430\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0442, \u043f\u043e\u0442\u043e\u043c \u0442\u0440\u0430\u0442\u044f\u0442 (\u0440\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u0443\u0435\u0442\u0441\u044f)";
  this.ak0 = "\u0431\u0438\u0437\u043d\u0435\u0441\u044b \u0438 \u0447\u0430\u0441\u0442\u043d\u044b\u0435 \u043b\u0438\u0446\u0430, \u0443 \u0432\u0441\u0435\u0445 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u044b\u0435 \u043b\u0438\u043d\u0438\u0438";
  this.ajT = "\u0412\u0430\u0448 \u0441\u0447\u0451\u0442 \u043d\u0430\u0447\u0438\u043d\u0430\u0435\u0442\u0441\u044f \u0441 \u043d\u0443\u043b\u044f \u0438 \u043d\u0438\u0436\u0435 \u043d\u0443\u043b\u044f \u043d\u0435 \u043e\u043f\u0443\u0441\u043a\u0430\u0435\u0442\u0441\u044f. \u041f\u0440\u043e\u0434\u0430\u0439\u0442\u0435 \u0447\u0442\u043e-\u043d\u0438\u0431\u0443\u0434\u044c \u0438\u043b\u0438 \u0441\u0434\u0435\u043b\u0430\u0439\u0442\u0435 \u0440\u0430\u0431\u043e\u0442\u0443 \u0434\u043b\u044f \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0430 \u2014 \u0438 \u0442\u0440\u0430\u0442\u044c\u0442\u0435 \u0437\u0430\u0440\u0430\u0431\u043e\u0442\u0430\u043d\u043d\u043e\u0435.";
  this.aj3 = "\u0423 \u0441\u0447\u0451\u0442\u0430 \u0447\u0430\u0441\u0442\u043d\u043e\u0433\u043e \u043b\u0438\u0446\u0430 \u0432 \u044d\u0442\u043e\u0439 \u043e\u0431\u0449\u0438\u043d\u0435 \u043d\u0435\u0442 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u043e\u0439 \u043b\u0438\u043d\u0438\u0438: \u0441\u043d\u0430\u0447\u0430\u043b\u0430 \u0437\u0430\u0440\u0430\u0431\u043e\u0442\u0430\u0442\u044c, \u043f\u043e\u0442\u043e\u043c \u0442\u0440\u0430\u0442\u0438\u0442\u044c.";
  this.akG = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430 \u043e\u0431\u0449\u0438\u043d\u044b";
  this.akF = "\u043d\u0430\u0447\u0430\u043b\u044c\u043d\u044b\u0439 \u0442\u0435\u043a\u0441\u0442: \u0435\u0433\u043e \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0442 \u043a\u0430\u0436\u0434\u044b\u0439 \u043d\u043e\u0432\u0438\u0447\u043e\u043a. \u041f\u0440\u0435\u0436\u0434\u0435 \u0447\u0435\u043c \u043d\u0430 \u043d\u0435\u0433\u043e \u043f\u043e\u043b\u0430\u0433\u0430\u0442\u044c\u0441\u044f, \u043f\u043e\u043a\u0430\u0436\u0438\u0442\u0435 \u0435\u0433\u043e \u044e\u0440\u0438\u0441\u0442\u0443.";
  this.al6 = "1. \u041e\u0431\u0449\u0438\u043d\u0430 \u0432\u0435\u0434\u0451\u0442 \u043e\u0431\u0449\u0438\u0439 \u0441\u0447\u0451\u0442 \u0442\u043e\u0433\u043e, \u0447\u0442\u043e \u0435\u0451 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0438 \u0434\u0430\u044e\u0442 \u0434\u0440\u0443\u0433 \u0434\u0440\u0443\u0433\u0443 \u0438 \u0431\u0435\u0440\u0443\u0442 \u0434\u0440\u0443\u0433 \u0443 \u0434\u0440\u0443\u0433\u0430. \u0415\u0434\u0438\u043d\u0438\u0446\u0430 \u2014 \u043c\u0435\u0440\u0430 \u0432 \u044d\u0442\u043e\u043c \u0441\u0447\u0451\u0442\u0435; \u0432 \u0446\u0435\u043d\u0430\u0445 \u043e\u043d\u0430 \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u043e\u0434\u043d\u0430 \u0435\u0434\u0438\u043d\u0438\u0446\u0430 \u043d\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0439 \u0432\u0430\u043b\u044e\u0442\u044b.\n2. \u0415\u0434\u0438\u043d\u0438\u0446\u044b \u2014 \u043d\u0435 \u0434\u0435\u043d\u044c\u0433\u0438. \u041d\u0438\u043a\u0442\u043e \u0438 \u043d\u0438\u043a\u043e\u0433\u0434\u0430 \u043d\u0435 \u043f\u0440\u043e\u0434\u0430\u0451\u0442, \u043d\u0435 \u043f\u043e\u043a\u0443\u043f\u0430\u0435\u0442 \u0438 \u043d\u0435 \u043e\u0431\u043c\u0435\u043d\u0438\u0432\u0430\u0435\u0442 \u0438\u0445 \u043d\u0430 \u0434\u0435\u043d\u044c\u0433\u0438.\n3. \u0411\u0430\u043b\u0430\u043d\u0441 \u0432\u044b\u0448\u0435 \u043d\u0443\u043b\u044f \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442, \u043d\u0430\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a \u0434\u0430\u043b \u0431\u043e\u043b\u044c\u0448\u0435, \u0447\u0435\u043c \u0432\u0437\u044f\u043b; \u0431\u0430\u043b\u0430\u043d\u0441 \u043d\u0438\u0436\u0435 \u043d\u0443\u043b\u044f \u2014 \u043d\u0430\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u043e\u043d \u0432\u0437\u044f\u043b \u0431\u043e\u043b\u044c\u0448\u0435, \u0447\u0435\u043c \u0434\u0430\u043b, \u0438 \u0434\u043e\u043b\u0436\u0435\u043d \u0432\u0435\u0440\u043d\u0443\u0442\u044c \u043e\u0431\u0449\u0438\u043d\u0435 \u0441\u0432\u043e\u0438\u043c\u0438 \u0442\u043e\u0432\u0430\u0440\u0430\u043c\u0438 \u0438 \u0443\u0441\u043b\u0443\u0433\u0430\u043c\u0438.\n4. \u0423 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0430 \u0435\u0441\u0442\u044c \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u0430\u044f \u043b\u0438\u043d\u0438\u044f \u0438 \u043f\u043e\u0442\u043e\u043b\u043e\u043a; \u0438\u0445 \u0437\u0430\u0434\u0430\u0451\u0442 \u043e\u0431\u0449\u0438\u043d\u0430 \u0438 \u043c\u043e\u0436\u0435\u0442 \u043c\u0435\u043d\u044f\u0442\u044c.\n5. \u0423\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u043e\u0432 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0442 \u043e\u0431\u0449\u0438\u043d\u0430, \u0438 \u043e\u043d\u0430 \u0437\u043d\u0430\u0435\u0442 \u0438\u0445 \u043f\u043e \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0438\u043c \u0438\u043c\u0435\u043d\u0430\u043c.\n6. \u041f\u0440\u043e\u0434\u0430\u0436\u0430 \u0437\u0430 \u0435\u0434\u0438\u043d\u0438\u0446\u044b \u2014 \u044d\u0442\u043e \u043f\u0440\u043e\u0434\u0430\u0436\u0430. \u041a\u0430\u0436\u0434\u044b\u0439 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a \u0441\u0430\u043c \u0432\u044b\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u0441\u0447\u0435\u0442\u0430 \u0438 \u0441\u0430\u043c \u043f\u043b\u0430\u0442\u0438\u0442 \u043d\u0430\u043b\u043e\u0433\u0438, \u0434\u0435\u043d\u044c\u0433\u0430\u043c\u0438, \u043a\u0430\u043a \u0441 \u043b\u044e\u0431\u043e\u0439 \u043f\u0440\u043e\u0434\u0430\u0436\u0438.\n7. \u0423\u0447\u0430\u0441\u0442\u043d\u0438\u043a \u043c\u043e\u0436\u0435\u0442 \u0432\u044b\u0439\u0442\u0438 \u0432 \u043b\u044e\u0431\u043e\u0435 \u0432\u0440\u0435\u043c\u044f, \u043f\u0440\u0438\u0432\u0435\u0434\u044f \u0431\u0430\u043b\u0430\u043d\u0441 \u043a \u043d\u0443\u043b\u044e. \u0412\u044b\u0448\u0435\u0434\u0448\u0438\u0439 \u0441 \u0431\u0430\u043b\u0430\u043d\u0441\u043e\u043c \u043d\u0438\u0436\u0435 \u043d\u0443\u043b\u044f \u043f\u043e\u0433\u0430\u0448\u0430\u0435\u0442 \u0440\u0430\u0437\u043d\u0438\u0446\u0443 \u0434\u0435\u043d\u044c\u0433\u0430\u043c\u0438 \u0432 \u0442\u0435\u0447\u0435\u043d\u0438\u0435 30 \u0434\u043d\u0435\u0439.\n8. \u041e\u0431\u0449\u0438\u043d\u0430 \u043c\u043e\u0436\u0435\u0442 \u0437\u0430\u043a\u0440\u044b\u0442\u044c \u0441\u0447\u0451\u0442 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0430, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u043d\u0430\u0440\u0443\u0448\u0430\u0435\u0442 \u044d\u0442\u0438 \u043f\u0440\u0430\u0432\u0438\u043b\u0430.";
  this.ag1 = "\u041f\u0440\u0438\u043d\u0438\u043c\u0430\u044e";
  this.akD = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430";
  this.akH = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430 \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u044b";
  this.akE = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430 \u043e\u0431\u0449\u0438\u043d\u044b \u0438\u0437\u043c\u0435\u043d\u0438\u043b\u0438\u0441\u044c: \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u0438 \u043f\u0440\u0438\u043c\u0438\u0442\u0435 \u0438\u0445 \u0437\u0430\u043d\u043e\u0432\u043e.";
  this.ajL = "\u042d\u0442\u0430 \u043e\u0431\u0449\u0438\u043d\u0430 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u0431\u0438\u0437\u043d\u0435\u0441\u044b \u0438 \u0441\u0430\u043c\u043e\u0437\u0430\u043d\u044f\u0442\u044b\u0445.";
  this.ahq = "\u0421\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0432\u044b\u043f\u0438\u0441\u043a\u0443 (CSV)";
  this.al7 = "\u0421\u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u043d\u043e";
  this.al8 = "\u0412\u0430\u0448\u0438 \u0441\u0434\u0435\u043b\u043a\u0438 \u0432 \u0431\u0443\u0444\u0435\u0440\u0435 \u043e\u0431\u043c\u0435\u043d\u0430 \u0432 \u0432\u0438\u0434\u0435 CSV: \u0432\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u0438\u0445 \u0432 \u0442\u0430\u0431\u043b\u0438\u0446\u0443 \u0438\u043b\u0438 \u043f\u0435\u0440\u0435\u0434\u0430\u0439\u0442\u0435 \u0431\u0443\u0445\u0433\u0430\u043b\u0442\u0435\u0440\u0443. \u0421\u0434\u0435\u043b\u043a\u0430 \u0432 \u0435\u0434\u0438\u043d\u0438\u0446\u0430\u0445 \u2014 \u044d\u0442\u043e \u043f\u0440\u043e\u0434\u0430\u0436\u0430, \u043e\u043d\u0430 \u0443\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0438 \u043e\u0431\u043b\u0430\u0433\u0430\u0435\u0442\u0441\u044f \u043d\u0430\u043b\u043e\u0433\u043e\u043c \u043a\u0430\u043a \u043b\u044e\u0431\u0430\u044f \u0434\u0440\u0443\u0433\u0430\u044f.";
  this.ajl = "\u042d\u0442\u043e\u0442 \u0431\u0440\u0430\u0443\u0437\u0435\u0440 \u043d\u0435 \u0440\u0430\u0437\u0440\u0435\u0448\u0430\u0435\u0442 \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u0435 \u043a\u043e\u043f\u0438\u0440\u043e\u0432\u0430\u0442\u044c. \u0412\u044b\u0434\u0435\u043b\u0438\u0442\u0435 \u0442\u0430\u0431\u043b\u0438\u0446\u0443 \u0438 \u0441\u043a\u043e\u043f\u0438\u0440\u0443\u0439\u0442\u0435 \u0432\u0440\u0443\u0447\u043d\u0443\u044e.";
  this.aiw = "\u042f \u043f\u043e\u0442\u0435\u0440\u044f\u043b(\u0430) \u0441\u0432\u043e\u0438 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430";
  this.aix = "\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u0432\u043e\u0439 \u0441\u0447\u0451\u0442. \u042d\u0442\u043e \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u043e \u0441\u043e\u0437\u0434\u0430\u0441\u0442 \u043d\u043e\u0432\u044b\u0439 \u043a\u043b\u044e\u0447 \u0438 \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u0442 \u0432\u0430\u0448\u0443 \u043e\u0431\u0449\u0438\u043d\u0443 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044c, \u0447\u0442\u043e \u044d\u0442\u043e \u0432\u044b. \u041f\u043e\u0441\u043b\u0435 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u044f \u043a\u043b\u044e\u0447 \u043d\u0430\u0447\u043d\u0451\u0442 \u0434\u0435\u0440\u0436\u0430\u0442\u044c \u0441\u0447\u0451\u0442 \u0447\u0435\u0440\u0435\u0437 \u043d\u0435\u0434\u0435\u043b\u044e \u2014 \u0432\u0440\u0435\u043c\u044f, \u0447\u0442\u043e\u0431\u044b \u0432\u044b \u0443\u0441\u043f\u0435\u043b\u0438 \u043e\u0442\u043a\u0430\u0437\u0430\u0442\u044c, \u0435\u0441\u043b\u0438 \u043f\u0440\u043e\u0441\u0438\u043b \u043a\u0442\u043e-\u0442\u043e \u0434\u0440\u0443\u0433\u043e\u0439.";
  this.aig = "\u042d\u0442\u043e \u043c\u043e\u0439 \u0441\u0447\u0451\u0442";
  this.agr = "\u0412\u044b \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u043b\u0438 \u0432\u0435\u0440\u043d\u0443\u0442\u044c \u0441\u0447\u0451\u0442";
  this.ajC = "\u0415\u0449\u0451 \u043d\u0435\u0442: \u0441\u0440\u043e\u043a \u043e\u0436\u0438\u0434\u0430\u043d\u0438\u044f \u043d\u0435 \u043f\u0440\u043e\u0448\u0451\u043b.";
  this.agw = "\u041f\u0440\u0438\u043d\u044f\u0442\u044c \u0441\u0447\u0451\u0442";
  this.ahR = "\u0417\u0430\u0431\u044b\u0442\u044c";
  this.agT = "\u042d\u0442\u043e \u043d\u0435 \u044f: \u043e\u0442\u043c\u0435\u043d\u0438\u0442\u044c";
  this.akv = "\u041e\u0442\u043c\u0435\u043d\u0435\u043d\u043e: \u0442\u043e \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u043e \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043f\u043e\u043b\u0443\u0447\u0438\u0442.";
  this.akt = "\u041a\u0442\u043e \u043f\u0440\u043e\u0441\u0438\u0442 \u0432\u0435\u0440\u043d\u0443\u0442\u044c \u0441\u0447\u0451\u0442";
  this.aks = "\u041f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0439\u0442\u0435, \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u0443\u0432\u0435\u0440\u0435\u043d\u044b, \u0447\u0442\u043e \u044d\u0442\u043e \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a: \u043f\u043e\u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0435 \u0441 \u043d\u0438\u043c, \u043d\u0435 \u0432\u0435\u0440\u044c\u0442\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u044e. \u0421\u0442\u0430\u0440\u044b\u0435 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430 \u0441\u0447\u0451\u0442\u0430 \u0435\u0449\u0451 \u043d\u0435\u0434\u0435\u043b\u044e \u043c\u043e\u0433\u0443\u0442 \u043e\u0442\u043c\u0435\u043d\u0438\u0442\u044c.";
