  this.ahL = "\u041f\u043e\u0434\u0440\u043e\u0431\u043d\u0435\u0435";
  this.akl = "\u0426\u0435\u043d\u0430";
  this.akm = "\u043e\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u043f\u0443\u0441\u0442\u044b\u043c: \u043f\u043e \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0451\u043d\u043d\u043e\u0441\u0442\u0438";
  this.agN = "\u043f\u043e \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0451\u043d\u043d\u043e\u0441\u0442\u0438";
  this.aib = "\u0415\u0434\u0438\u043d\u0438\u0446\u0430\u043c\u0438, %";
  this.aic = "\u043a\u0430\u043a\u0443\u044e \u0434\u043e\u043b\u044e \u0446\u0435\u043d\u044b \u0432\u044b \u0431\u0435\u0440\u0451\u0442\u0435 \u0438\u043b\u0438 \u043f\u043b\u0430\u0442\u0438\u0442\u0435 \u0435\u0434\u0438\u043d\u0438\u0446\u0430\u043c\u0438: 100 \u2014 \u0432\u0441\u044e, 50 \u2014 \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0443";
