  this.ak6 = "\u0421\u043a\u043e\u043b\u044c\u043a\u043e \u0441\u0430\u043c\u043e\u0435 \u0431\u043e\u043b\u044c\u0448\u0435\u0435 \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u0434\u043e\u043b\u0436\u0435\u043d \u0447\u0435\u043b\u043e\u0432\u0435\u043a";
