  this.ald = "\u0423\u0431\u0440\u0430\u0442\u044c \u043a\u0430\u0440\u0442\u043e\u0447\u043a\u0443? \u0421 \u044d\u0442\u043e\u0433\u043e \u043c\u043e\u043c\u0435\u043d\u0442\u0430 \u043f\u0435\u0447\u0430\u0442\u0438 \u043d\u0430 \u043d\u0435\u0451 \u043d\u0438\u043a\u0442\u043e \u043d\u0435 \u043f\u043e\u043b\u0443\u0447\u0438\u0442.";
  this.agU = "\u041a\u0430\u0440\u0442\u043e\u0447\u043a\u0430 \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0430";
  this.ahU = "\u041f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c \u043f\u0435\u0447\u0430\u0442\u044c";
  this.ahV = "\u041f\u0443\u0441\u0442\u044c \u043f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u044c \u043d\u0430\u0432\u0435\u0434\u0451\u0442 \u043a\u0430\u043c\u0435\u0440\u0443 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0430 \u043d\u0430 \u044d\u0442\u043e\u0442 \u043a\u043e\u0434: \u043e\u0442\u043a\u0440\u043e\u0435\u0442\u0441\u044f \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435, \u0438 \u043f\u0435\u0447\u0430\u0442\u044c \u043f\u043e\u044f\u0432\u0438\u0442\u0441\u044f \u043d\u0430 \u0435\u0433\u043e \u043a\u0430\u0440\u0442\u043e\u0447\u043a\u0435. \u041a\u043e\u0434 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u043e\u0434\u0438\u043d \u0440\u0430\u0437, \u0434\u0435\u0441\u044f\u0442\u044c \u043c\u0438\u043d\u0443\u0442.";
  this.ahS = "\u0412\u044b\u0434\u0430\u0442\u044c \u043d\u0430\u0433\u0440\u0430\u0434\u0443";
  this.ahT = "\u041f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u044c \u0441 \u0437\u0430\u043f\u043e\u043b\u043d\u0435\u043d\u043d\u043e\u0439 \u043a\u0430\u0440\u0442\u043e\u0447\u043a\u043e\u0439 \u0441\u043a\u0430\u043d\u0438\u0440\u0443\u0435\u0442 \u044d\u0442\u043e\u0442 \u043a\u043e\u0434: \u043d\u0430\u0433\u0440\u0430\u0434\u0430 \u0441\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0441 \u043a\u0430\u0440\u0442\u043e\u0447\u043a\u0438, \u0438 \u0435\u0433\u043e \u044d\u043a\u0440\u0430\u043d \u044d\u0442\u043e \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442. \u041a\u043e\u0434 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u043e\u0434\u0438\u043d \u0440\u0430\u0437, \u0434\u0435\u0441\u044f\u0442\u044c \u043c\u0438\u043d\u0443\u0442.";
  this.aiY = "\u041d\u043e\u0432\u044b\u0439 \u043a\u043e\u0434";
  this.al2 = "\u041f\u0435\u0447\u0430\u0442\u044c";
  this.akC = "\u041d\u0430\u0433\u0440\u0430\u0434\u0430";
  this.ahf = "\u042d\u0442\u043e\u0442 \u043a\u043e\u0434 \u0443\u0436\u0435 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d: \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u0435 \u043d\u043e\u0432\u044b\u0439.";
  this.ahe = "\u042d\u0442\u043e\u0442 \u043a\u043e\u0434 \u0443\u0441\u0442\u0430\u0440\u0435\u043b: \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u0435 \u043d\u043e\u0432\u044b\u0439.";
  this.ahd = "\u042d\u0442\u043e \u043d\u0435 \u043a\u043e\u0434 \u043c\u0430\u0433\u0430\u0437\u0438\u043d\u0430.";
  this.ajm = "\u041a\u0430\u0440\u0442\u043e\u0447\u043a\u0430 \u0435\u0449\u0451 \u043d\u0435 \u0437\u0430\u043f\u043e\u043b\u043d\u0435\u043d\u0430.";
  this.aja = "\u0423 \u044d\u0442\u043e\u0433\u043e \u043c\u0430\u0433\u0430\u0437\u0438\u043d\u0430 \u0441\u0435\u0439\u0447\u0430\u0441 \u043d\u0435\u0442 \u043a\u0430\u0440\u0442\u043e\u0447\u043a\u0438.";
  this.ajU = "\u042d\u0442\u043e \u043a\u043e\u0434 \u0432\u0430\u0448\u0435\u0433\u043e \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0433\u043e \u043c\u0430\u0433\u0430\u0437\u0438\u043d\u0430.";
  this.ajK = "\u042d\u0442\u043e\u0439 \u043e\u0431\u0449\u0438\u043d\u043e\u0439 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442 \u043e\u0434\u043d\u043e \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u043e. \u0415\u0441\u043b\u0438 \u043e\u043d\u043e \u043f\u043e\u0442\u0435\u0440\u044f\u0435\u0442\u0441\u044f, \u043d\u0438\u043a\u0442\u043e \u043d\u0435 \u0441\u043c\u043e\u0436\u0435\u0442 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0442\u044c \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u043e\u0432 \u0438 \u0437\u0430\u0434\u0430\u0432\u0430\u0442\u044c \u043b\u0438\u043c\u0438\u0442\u044b, \u043f\u043e\u043a\u0430 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0438 \u043d\u0435 \u0432\u044b\u0431\u0435\u0440\u0443\u0442 \u043d\u043e\u0432\u043e\u0433\u043e \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0435\u0433\u043e. \u0414\u043e\u0431\u0430\u0432\u044c\u0442\u0435 \u0432\u0442\u043e\u0440\u043e\u0433\u043e \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0435\u0433\u043e \u0441\u0435\u0439\u0447\u0430\u0441 \u2014 \u0434\u0440\u0443\u0433\u043e\u0435 \u0441\u0432\u043e\u0451 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u043e \u0438\u043b\u0438 \u0447\u0435\u043b\u043e\u0432\u0435\u043a\u0430, \u043a\u043e\u0442\u043e\u0440\u043e\u043c\u0443 \u0434\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0435.";
  this.aiA = "\u0423\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0438\u0435";
  this.ahF = "\u0412\u044b\u0431\u0440\u0430\u0442\u044c \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0435\u0433\u043e";
  this.ahI = "\u0421\u043a\u043e\u043b\u044c\u043a\u043e \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u043e\u0432 \u043d\u0430\u0437\u0432\u0430\u043b\u0438";
  this.ahG = "\u043a\u043b\u044e\u0447 \u043f\u043e\u043a\u0430 \u043d\u0438\u043a\u0442\u043e \u043d\u0435 \u043d\u0430\u0437\u0432\u0430\u043b";
  this.ahD = "\u041a\u043b\u044e\u0447 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430 \u043d\u043e\u0432\u043e\u0433\u043e \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0435\u0433\u043e";
  this.ahE = "\u043a\u043b\u044e\u0447 \u044d\u0442\u043e\u0433\u043e \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430, \u0435\u0441\u043b\u0438 \u043d\u0435 \u0432\u043f\u0438\u0441\u0430\u0442\u044c \u0434\u0440\u0443\u0433\u043e\u0439: \u043e\u043d \u043f\u043e\u043a\u0430\u0437\u0430\u043d \u0442\u0430\u043c \u0432 \u00ab\u0414\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u044d\u0442\u043e \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u043e\u00bb";
  this.ahJ = "\u041d\u0430\u0437\u0432\u0430\u0442\u044c \u044d\u0442\u043e\u0442 \u043a\u043b\u044e\u0447";
  this.ahC = "\u041d\u043e\u0432\u044b\u0439 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0438\u0439 \u0442\u0435\u043f\u0435\u0440\u044c \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442. \u041d\u0430 \u0442\u043e\u043c \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0435: \u00ab\u0421\u0447\u0435\u0442\u0430\u00bb, \u00ab\u041e\u0442\u043a\u0440\u044b\u0442\u044c \u0438\u043b\u0438 \u0434\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u0435\u0449\u0451\u00bb, \u00ab\u0414\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u044d\u0442\u043e \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u043e \u043a \u043c\u043e\u0435\u043c\u0443 \u0441\u0447\u0451\u0442\u0443\u00bb \u2014 \u0441 \u0438\u0434\u0435\u043d\u0442\u0438\u0444\u0438\u043a\u0430\u0442\u043e\u0440\u043e\u043c \u0441\u0447\u0451\u0442\u0430 \u043e\u0431\u0449\u0438\u043d\u044b.";
  this.ahB = "\u041d\u0430\u0437\u0432\u0430\u043b\u043e \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u043e\u0432: \u043a\u043b\u044e\u0447 \u043e\u0431\u044a\u044f\u0432\u043b\u0435\u043d \u0432 \u0446\u0435\u043f\u043e\u0447\u043a\u0435 \u043e\u0431\u0449\u0438\u043d\u044b.";
  this.ahH = "\u042d\u0442\u0430 \u043e\u0431\u0449\u0438\u043d\u0430 \u043e\u0442\u043a\u0440\u044b\u0442\u0430 \u0434\u043b\u044f \u0432\u0441\u0435\u0445, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u0435\u0451 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0438 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0435\u0433\u043e \u043d\u0435 \u0432\u044b\u0431\u0438\u0440\u0430\u044e\u0442: \u043b\u044e\u0431\u043e\u0439 \u043c\u043e\u0433 \u0431\u044b \u043f\u0440\u043e\u0433\u043e\u043b\u043e\u0441\u043e\u0432\u0430\u0442\u044c \u0437\u0430 \u0441\u0435\u0431\u044f. \u0414\u0435\u0440\u0436\u0438\u0442\u0435 \u0434\u0432\u0443\u0445 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0438\u0445.";
  this.ahK = "\u0413\u043e\u043b\u043e\u0441 \u0435\u0441\u0442\u044c \u0442\u043e\u043b\u044c\u043a\u043e \u0443 \u0442\u0435\u0445, \u043a\u0442\u043e \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a \u043d\u0435 \u043c\u0435\u043d\u044c\u0448\u0435 \u043c\u0435\u0441\u044f\u0446\u0430.";
  this.aiG = "\u041f\u0435\u0440\u0435\u043d\u0435\u0441\u0442\u0438 \u0438\u043b\u0438 \u0441\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c \u043a\u043e\u043f\u0438\u044e";
  this.aiH = "\u0421\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u0435 \u043a\u043e\u043f\u0438\u044e \u0432\u0441\u0435\u0439 \u043e\u0431\u0449\u0438\u043d\u044b \u2014 \u0437\u0430\u043f\u0438\u0441\u0438 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0441\u0447\u0451\u0442\u0430, \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u043e\u0432, \u043f\u0440\u0430\u0432\u0438\u043b\u0430, \u043a\u043b\u044e\u0447 \u043e\u0431\u0449\u0438\u043d\u044b \u2014 \u043e\u0434\u043d\u0438\u043c \u0444\u0430\u0439\u043b\u043e\u043c. \u0425\u0440\u0430\u043d\u0438\u0442\u0435 \u043a\u043e\u043f\u0438\u0438; \u0441 \u043d\u0435\u0439 \u043e\u0431\u0449\u0438\u043d\u0443 \u043c\u043e\u0436\u043d\u043e \u043f\u0435\u0440\u0435\u043d\u0435\u0441\u0442\u0438 \u043d\u0430 \u0434\u0440\u0443\u0433\u043e\u0439 \u0445\u0430\u0431 \u0438\u043b\u0438 \u043d\u0430 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0443\u0437\u0435\u043b \u2014 \u0442\u0430\u043c, \u0433\u0434\u0435 \u043e\u0431\u0449\u0438\u043d\u044b \u0441\u043e\u0437\u0434\u0430\u044e\u0442\u0441\u044f. \u041a\u043e\u0433\u0434\u0430 \u043e\u043d\u0430 \u0443\u0436\u0435 \u0442\u0430\u043c, \u0437\u0430\u043a\u0440\u043e\u0439\u0442\u0435 \u0435\u0451 \u0437\u0434\u0435\u0441\u044c.";
  this.ahn = "\u0412 \u0444\u0430\u0439\u043b\u0435 \u043a\u043b\u044e\u0447 \u043e\u0431\u0449\u0438\u043d\u044b: \u0443 \u043a\u043e\u0433\u043e \u043e\u043d \u0435\u0441\u0442\u044c, \u0442\u043e\u0442 \u043c\u043e\u0436\u0435\u0442 \u0434\u0435\u0439\u0441\u0442\u0432\u043e\u0432\u0430\u0442\u044c \u043a\u0430\u043a \u0435\u0451 \u0443\u0437\u0435\u043b. \u0425\u0440\u0430\u043d\u0438\u0442\u0435 \u0435\u0433\u043e \u043a\u0430\u043a \u043a\u043b\u044e\u0447.";
  this.akJ = "\u0421\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c \u043a\u043e\u043f\u0438\u044e";
  this.aho = "\u0421\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u043e";
  this.ahp = "\u041a\u043e\u043f\u0438\u044f \u2014 \u0432 \u0437\u0430\u0433\u0440\u0443\u0437\u043a\u0430\u0445 \u0432\u0430\u0448\u0435\u0433\u043e \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430.";
  this.ajt = "\u041a\u043e\u043f\u0438\u044f \u043d\u0435 \u0441\u043e\u0445\u0440\u0430\u043d\u0438\u043b\u0430\u0441\u044c.";
  this.ah7 = "\u041e\u043d\u0430 \u043f\u0435\u0440\u0435\u0435\u0445\u0430\u043b\u0430: \u0437\u0430\u043a\u0440\u044b\u0442\u044c \u0437\u0434\u0435\u0441\u044c";
  this.ah9 = "\u041a\u043e\u0433\u0434\u0430 \u043e\u0431\u0449\u0438\u043d\u0430 \u0443\u0436\u0435 \u043f\u0435\u0440\u0435\u043d\u0435\u0441\u0435\u043d\u0430 \u043d\u0430 \u043d\u043e\u0432\u043e\u0435 \u043c\u0435\u0441\u0442\u043e, \u0437\u0430\u043a\u0440\u043e\u0439\u0442\u0435 \u0435\u0451 \u0437\u0434\u0435\u0441\u044c: \u0441 \u044d\u0442\u043e\u0433\u043e \u043c\u043e\u043c\u0435\u043d\u0442\u0430 \u044d\u0442\u043e\u0442 \u0445\u0430\u0431 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442, \u0430 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0430, \u043f\u0440\u0438\u0448\u0435\u0434\u0448\u0435\u0435 \u0441\u044e\u0434\u0430, \u043e\u0442\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u043f\u043e \u043d\u043e\u0432\u043e\u043c\u0443 \u0430\u0434\u0440\u0435\u0441\u0443.";
