  this.amB = "\u0437\u0430 \u0434\u043e\u043c\u043e\u0432\u043b\u0435\u043d\u0456\u0441\u0442\u044e";
  this.anZ = "\u041e\u0434\u0438\u043d\u0438\u0446\u044f\u043c\u0438, %";
