  this.aqM = "\u0420\u0430\u0445\u0443\u043d\u043e\u043a \u0440\u043e\u0434\u0438\u043d\u0438 \u0447\u0438 \u043a\u043e\u043c\u0430\u043d\u0434\u0438 \u0442\u0440\u0438\u043c\u0430\u044e\u0442\u044c \u0440\u0430\u0445\u0443\u043d\u043a\u0438 \u0457\u0457 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432, \u0430 \u043d\u0435 \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u0457: \u043a\u043e\u0436\u0435\u043d \u0442\u0440\u0438\u043c\u0430\u0447 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0454\u0442\u044c\u0441\u044f \u043d\u0438\u043c \u0456\u0437 \u0431\u0443\u0434\u044c-\u044f\u043a\u043e\u0433\u043e \u0441\u0432\u043e\u0433\u043e \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u044e, \u0430 \u0432\u0442\u0440\u0430\u0447\u0435\u043d\u0438\u0439 \u0442\u0435\u043b\u0435\u0444\u043e\u043d \u0437\u0430\u043c\u0456\u043d\u044e\u0454\u0442\u044c\u0441\u044f \u043e\u0434\u0438\u043d \u0440\u0430\u0437 \u2014 \u0443 \u0432\u043b\u0430\u0441\u043d\u043e\u043c\u0443 \u0440\u0430\u0445\u0443\u043d\u043a\u0443 \u043b\u044e\u0434\u0438\u043d\u0438.";
  this.aoX = "\u0441\u043f\u0456\u043b\u044c\u043d\u0438\u0445 \u0440\u0430\u0445\u0443\u043d\u043a\u0456\u0432 \u043f\u043e\u043a\u0438 \u043d\u0435\u043c\u0430\u0454";
  this.aoJ = "\u041d\u043e\u0432\u0438\u0439 \u0441\u043f\u0456\u043b\u044c\u043d\u0438\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a";
  this.aqI = "\u041d\u0430\u0437\u0432\u0430";
  this.aqJ = "\u0421\u043f\u0435\u0440\u0448\u0443 \u0432\u0456\u0434\u043a\u0440\u0438\u0439\u0442\u0435 \u0441\u0432\u0456\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a: \u0441\u043f\u0456\u043b\u044c\u043d\u0438\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u0442\u0440\u0438\u043c\u0430\u044e\u0442\u044c \u0440\u0430\u0445\u0443\u043d\u043a\u0438 \u0439\u043e\u0433\u043e \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432.";
  this.aqL = "\u0420\u0430\u0445\u0443\u043d\u043e\u043a \u0432\u0456\u0434\u043a\u0440\u0438\u0442\u043e, \u0432\u0438 \u0439\u043e\u0433\u043e \u0442\u0440\u0438\u043c\u0430\u0447. \u0412\u043b\u0430\u0441\u043d\u043e\u0457 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u043e\u0457 \u043b\u0456\u043d\u0456\u0457 \u0432\u0456\u043d \u043d\u0435 \u043c\u0430\u0454: \u0432\u0438\u0442\u0440\u0430\u0447\u0430\u0454 \u0442\u0435, \u0449\u043e \u0439\u043e\u043c\u0443 \u0437\u0430\u043f\u043b\u0430\u0442\u0438\u043b\u0438, \u0430\u0431\u043e \u043b\u0456\u043d\u0456\u044e, \u044f\u043a\u0443 \u0439\u043e\u043c\u0443 \u043f\u043e\u0437\u0438\u0447\u0438\u0432 \u0443\u0447\u0430\u0441\u043d\u0438\u043a. \u0406\u043d\u0448\u0438\u0445 \u0434\u043e\u0434\u0430\u0439\u0442\u0435 \u0432 \u0440\u043e\u0437\u0434\u0456\u043b\u0456 \u00ab\u0422\u0440\u0438\u043c\u0430\u0447\u0456\u00bb.";
