  this.anP = "\u0423\u0447\u0430\u0441\u043d\u0438\u043a";
  this.arA = "\u0432\u0438";
  this.arg = "\u0414\u0432\u0430 \u043f\u0456\u0434\u043f\u0438\u0441\u0438";
