  this.arf = "\u0437\u0430\u043b\u0438\u0448\u0442\u0435 \u043f\u043e\u0440\u043e\u0436\u043d\u0456\u043c: \u0434\u043b\u044f \u0431\u0443\u0434\u044c-\u044f\u043a\u043e\u0433\u043e \u043f\u043b\u0430\u0442\u0435\u0436\u0443 \u0434\u043e\u0441\u0438\u0442\u044c \u043e\u0434\u043d\u043e\u0433\u043e \u0442\u0440\u0438\u043c\u0430\u0447\u0430";
  this.ari = "\u0412\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043e";
  this.arh = "\u0422\u0435\u043f\u0435\u0440 \u0434\u043b\u044f \u0431\u0443\u0434\u044c-\u044f\u043a\u043e\u0433\u043e \u043f\u043b\u0430\u0442\u0435\u0436\u0443 \u0434\u043e\u0441\u0438\u0442\u044c \u043e\u0434\u043d\u043e\u0433\u043e \u0442\u0440\u0438\u043c\u0430\u0447\u0430.";
  this.arc = "\u041f\u043b\u0430\u0442\u0435\u0436\u0456, \u0449\u043e \u0447\u0435\u043a\u0430\u044e\u0442\u044c \u043d\u0430 \u0434\u0440\u0443\u0433\u043e\u0433\u043e \u0442\u0440\u0438\u043c\u0430\u0447\u0430";
  this.arb = "\u041f\u043b\u0430\u0442\u0456\u0436 \u043f\u043e\u043d\u0430\u0434 \u043f\u043e\u0440\u0456\u0433 \u0440\u0430\u0445\u0443\u043d\u043a\u0443 \u043f\u0440\u043e\u043f\u043e\u043d\u0443\u0454 \u043e\u0434\u0438\u043d \u0442\u0440\u0438\u043c\u0430\u0447, \u0430 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0443\u0454 \u0456\u043d\u0448\u0438\u0439. \u041d\u0435 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043d\u0438\u0439 \u0437\u0430 \u0442\u0438\u0436\u0434\u0435\u043d\u044c \u043f\u043b\u0430\u0442\u0456\u0436 \u0432\u0456\u0434\u043f\u0430\u0434\u0430\u0454.";
  this.apt = "\u043d\u0456\u0447\u043e\u0433\u043e \u043d\u0435 \u0447\u0435\u043a\u0430\u0454";
  this.ana = "\u041f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0438 \u0439 \u0437\u0430\u043f\u043b\u0430\u0442\u0438\u0442\u0438";
  this.aqc = "\u0417\u0430\u043f\u0440\u043e\u043f\u043e\u043d\u0443\u0432\u0430\u0432";
  this.aqb = "\u041f\u043b\u0430\u0442\u0456\u0436 \u0447\u0435\u043a\u0430\u0454 \u043d\u0430 \u0434\u0440\u0443\u0433\u043e\u0433\u043e \u0442\u0440\u0438\u043c\u0430\u0447\u0430";
  this.aoB = "\u0426\u0435\u0439 \u043f\u043b\u0430\u0442\u0456\u0436 \u0437\u0430\u043f\u0440\u043e\u043f\u043e\u043d\u0443\u0432\u0430\u043b\u0438 \u0432\u0438: \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0438 \u0439\u043e\u0433\u043e \u043c\u0430\u0454 \u0456\u043d\u0448\u0438\u0439 \u0442\u0440\u0438\u043c\u0430\u0447.";
  this.aoC = "\u0426\u044c\u043e\u043c\u0443 \u043f\u043b\u0430\u0442\u0435\u0436\u0443 \u043f\u043e\u0442\u0440\u0456\u0431\u0435\u043d \u0434\u0440\u0443\u0433\u0438\u0439 \u0442\u0440\u0438\u043c\u0430\u0447.";
  this.aq1 = "\u041f\u043e\u043b\u0456\u0442\u0438\u043a\u0430";
  this.aq7 = "\u0412\u043b\u0430\u0441\u043d\u0430 \u043f\u043e\u043b\u0456\u0442\u0438\u043a\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0438: \u0434\u0456\u0454 \u0437 \u043c\u043e\u043c\u0435\u043d\u0442\u0443 \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043d\u044f \u0434\u043b\u044f \u043a\u043e\u0436\u043d\u043e\u0433\u043e \u0440\u0430\u0445\u0443\u043d\u043a\u0443. \u041b\u0456\u043d\u0456\u0457, \u0432\u0438\u0434\u0430\u043d\u0456 \u0440\u0430\u043d\u0456\u0448\u0435, \u043b\u0438\u0448\u0430\u044e\u0442\u044c\u0441\u044f \u044f\u043a \u0454. \u0425\u0430\u0431, \u043d\u0430 \u044f\u043a\u043e\u043c\u0443 \u0441\u0442\u043e\u0457\u0442\u044c \u0433\u0440\u043e\u043c\u0430\u0434\u0430, \u043c\u043e\u0436\u0435 \u0434\u043e\u0437\u0432\u043e\u043b\u044f\u0442\u0438 \u043c\u0435\u043d\u0448\u0435, \u043d\u0456\u0436 \u043f\u0440\u043e\u043f\u043e\u043d\u0443\u044e\u0442\u044c \u0434\u0435\u0456\u043d\u0434\u0435.";
  this.aq3 = "\u0412\u0441\u0442\u0443\u043f \u0456 \u0431\u0456\u0437\u043d\u0435\u0441\u0438";
  this.aq4 = "\u041f\u0440\u0438\u0432\u0430\u0442\u043d\u0456 \u043e\u0441\u043e\u0431\u0438";
  this.aq5 = "\u041a\u0440\u0435\u0434\u0438\u0442 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u0456\u0439 \u043e\u0441\u043e\u0431\u0456, \u043d\u0430\u0432\u0456\u0442\u044c \u0431\u0435\u0437\u0432\u0456\u0434\u0441\u043e\u0442\u043a\u043e\u0432\u0438\u0439, \u043c\u043e\u0436\u0435 \u043f\u0456\u0434\u043f\u0430\u0434\u0430\u0442\u0438 \u043f\u0456\u0434 \u043f\u0440\u0430\u0432\u0438\u043b\u0430 \u0441\u043f\u043e\u0436\u0438\u0432\u0447\u043e\u0433\u043e \u043a\u0440\u0435\u0434\u0438\u0442\u0443. \u0414\u0435 \u043b\u044e\u0434\u0438 \u0441\u043f\u0435\u0440\u0448\u0443 \u0437\u0430\u0440\u043e\u0431\u043b\u044f\u044e\u0442\u044c, \u0430 \u043f\u043e\u0442\u0456\u043c \u0432\u0438\u0442\u0440\u0430\u0447\u0430\u044e\u0442\u044c, \u043a\u0440\u0435\u0434\u0438\u0442 \u043d\u0435 \u0432\u0438\u0434\u0430\u0454\u0442\u044c\u0441\u044f \u0456 \u043f\u0438\u0442\u0430\u043d\u043d\u044f \u043d\u0435 \u0432\u0438\u043d\u0438\u043a\u0430\u0454.";
  this.apR = "\u0431\u0456\u0437\u043d\u0435\u0441\u0438 \u0439 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u0456 \u043e\u0441\u043e\u0431\u0438 \u2014 \u043b\u0438\u0448\u0435 \u0437 \u043b\u0456\u043d\u0456\u0454\u044e, \u044f\u043a\u0443 \u043f\u043e\u0437\u0438\u0447\u0438\u0432 \u0443\u0447\u0430\u0441\u043d\u0438\u043a";
  this.apQ = "\u0431\u0456\u0437\u043d\u0435\u0441\u0438 \u0439 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u0456 \u043e\u0441\u043e\u0431\u0438 \u2014 \u043b\u0456\u043d\u0456\u044f \u043f\u0456\u0441\u043b\u044f \u0442\u043e\u0433\u043e, \u044f\u043a \u043b\u044e\u0434\u0438\u043d\u0430 \u0437\u0430\u0440\u043e\u0431\u0438\u043b\u0430";
  this.apS = "\u041a\u0440\u0435\u0434\u0438\u0442\u043d\u0430 \u043b\u0456\u043d\u0456\u044f \u043d\u043e\u0432\u043e\u0457 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u043e\u0457 \u043e\u0441\u043e\u0431\u0438";
  this.apT = "\u0442\u0430\u043c, \u0434\u0435 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u0456 \u043e\u0441\u043e\u0431\u0438 \u043c\u0430\u044e\u0442\u044c \u043b\u0456\u043d\u0456\u0457 \u0432\u0456\u0434 \u043f\u043e\u0447\u0430\u0442\u043a\u0443";
  this.apU = "\u0421\u043a\u0456\u043b\u044c\u043a\u0438 \u0449\u043e\u043d\u0430\u0439\u0431\u0456\u043b\u044c\u0448\u0435 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 \u0432\u0438\u043d\u043d\u0430 \u043b\u044e\u0434\u0438\u043d\u0430";
  this.apV = "\u0432\u043b\u0430\u0441\u043d\u0430 \u043b\u0456\u043d\u0456\u044f \u0439 \u043f\u043e\u0437\u0438\u0447\u0435\u043d\u0430 \u0440\u0430\u0437\u043e\u043c; \u0437\u0430\u043b\u0438\u0448\u0442\u0435 \u043f\u043e\u0440\u043e\u0436\u043d\u0456\u043c: \u0431\u0435\u0437 \u043e\u0431\u043c\u0435\u0436\u0435\u043d\u043d\u044f";
