  this.aq2 = "\u0422\u0430\u043a\u043e\u0457 \u043f\u043e\u043b\u0456\u0442\u0438\u043a\u0438 \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u043c\u0430\u0442\u0438 \u043d\u0435 \u043c\u043e\u0436\u0435: \u043f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u0441\u0443\u043c\u0438.";
