  this.apd = "\u0422\u043e\u0439, \u043a\u043e\u043c\u0443 \u0446\u0435 \u043f\u043e\u0441\u0438\u043b\u0430\u043d\u043d\u044f \u043f\u0440\u043e\u0441\u0438\u0442\u044c \u0437\u0430\u043f\u043b\u0430\u0442\u0438\u0442\u0438, \u043d\u0435 \u0443\u0447\u0430\u0441\u043d\u0438\u043a \u0446\u0456\u0454\u0457 \u0433\u0440\u043e\u043c\u0430\u0434\u0438.";
  this.amK = "\u041a\u0430\u0440\u0442\u043a\u0438";
