  this.anI = "\u041f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u0438 \u043f\u0435\u0447\u0430\u0442\u043a\u0443";
  this.anJ = "\u041d\u0435\u0445\u0430\u0439 \u043f\u043e\u043a\u0443\u043f\u0435\u0446\u044c \u043d\u0430\u0432\u0435\u0434\u0435 \u043a\u0430\u043c\u0435\u0440\u0443 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0430 \u043d\u0430 \u0446\u0435\u0439 \u043a\u043e\u0434: \u0432\u0456\u0434\u043a\u0440\u0438\u0454\u0442\u044c\u0441\u044f \u0437\u0430\u0441\u0442\u043e\u0441\u0443\u043d\u043e\u043a, \u0456 \u043f\u0435\u0447\u0430\u0442\u043a\u0430 \u0437\u2019\u044f\u0432\u0438\u0442\u044c\u0441\u044f \u043d\u0430 \u0439\u043e\u0433\u043e \u043a\u0430\u0440\u0442\u0446\u0456. \u041a\u043e\u0434 \u0434\u0456\u0454 \u043e\u0434\u0438\u043d \u0440\u0430\u0437, \u0434\u0435\u0441\u044f\u0442\u044c \u0445\u0432\u0438\u043b\u0438\u043d.";
