  this.anH = "\u041f\u043e\u043a\u0443\u043f\u0435\u0446\u044c \u0456\u0437 \u0437\u0430\u043f\u043e\u0432\u043d\u0435\u043d\u043e\u044e \u043a\u0430\u0440\u0442\u043a\u043e\u044e \u0441\u043a\u0430\u043d\u0443\u0454 \u0446\u0435\u0439 \u043a\u043e\u0434: \u0432\u0438\u043d\u0430\u0433\u043e\u0440\u043e\u0434\u0430 \u0441\u043f\u0438\u0441\u0443\u0454\u0442\u044c\u0441\u044f \u0437 \u043a\u0430\u0440\u0442\u043a\u0438, \u0456 \u0439\u043e\u0433\u043e \u0435\u043a\u0440\u0430\u043d \u0446\u0435 \u043f\u043e\u043a\u0430\u0437\u0443\u0454. \u041a\u043e\u0434 \u0434\u0456\u0454 \u043e\u0434\u0438\u043d \u0440\u0430\u0437, \u0434\u0435\u0441\u044f\u0442\u044c \u0445\u0432\u0438\u043b\u0438\u043d.";
  this.aoM = "\u041d\u043e\u0432\u0438\u0439 \u043a\u043e\u0434";
  this.aqQ = "\u041f\u0435\u0447\u0430\u0442\u043a\u0430";
  this.aqq = "\u0412\u0438\u043d\u0430\u0433\u043e\u0440\u043e\u0434\u0430";
  this.an3 = "\u0426\u0435\u0439 \u043a\u043e\u0434 \u0443\u0436\u0435 \u0432\u0438\u043a\u043e\u0440\u0438\u0441\u0442\u0430\u043d\u043e: \u043f\u043e\u043f\u0440\u043e\u0441\u0456\u0442\u044c \u043d\u043e\u0432\u0438\u0439.";
  this.an2 = "\u0426\u0435\u0439 \u043a\u043e\u0434 \u0437\u0430\u0441\u0442\u0430\u0440\u0456\u0432: \u043f\u043e\u043f\u0440\u043e\u0441\u0456\u0442\u044c \u043d\u043e\u0432\u0438\u0439.";
  this.an1 = "\u0426\u0435 \u043d\u0435 \u043a\u043e\u0434 \u043c\u0430\u0433\u0430\u0437\u0438\u043d\u0443.";
  this.apa = "\u041a\u0430\u0440\u0442\u043a\u0443 \u0449\u0435 \u043d\u0435 \u0437\u0430\u043f\u043e\u0432\u043d\u0435\u043d\u043e.";
  this.aoY = "\u0426\u0435\u0439 \u043c\u0430\u0433\u0430\u0437\u0438\u043d \u0437\u0430\u0440\u0430\u0437 \u043d\u0435 \u043c\u0430\u0454 \u043a\u0430\u0440\u0442\u043a\u0438.";
  this.apI = "\u0426\u0435 \u043a\u043e\u0434 \u0432\u0430\u0448\u043e\u0433\u043e \u0432\u043b\u0430\u0441\u043d\u043e\u0433\u043e \u043c\u0430\u0433\u0430\u0437\u0438\u043d\u0443.";
  this.apy = "\u0426\u0456\u0454\u044e \u0433\u0440\u043e\u043c\u0430\u0434\u043e\u044e \u043a\u0435\u0440\u0443\u0454 \u043e\u0434\u0438\u043d \u043f\u0440\u0438\u0441\u0442\u0440\u0456\u0439. \u042f\u043a\u0449\u043e \u0432\u0456\u043d \u0437\u0430\u0433\u0443\u0431\u0438\u0442\u044c\u0441\u044f, \u043d\u0456\u0445\u0442\u043e \u043d\u0435 \u0437\u043c\u043e\u0436\u0435 \u043f\u0440\u0438\u0439\u043c\u0430\u0442\u0438 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432 \u0456 \u0437\u0430\u0434\u0430\u0432\u0430\u0442\u0438 \u043b\u0456\u043c\u0456\u0442\u0438, \u0434\u043e\u043a\u0438 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0438 \u043d\u0435 \u043e\u0431\u0435\u0440\u0443\u0442\u044c \u043d\u043e\u0432\u043e\u0433\u043e \u043a\u0435\u0440\u0456\u0432\u043d\u0438\u043a\u0430. \u0414\u043e\u0434\u0430\u0439\u0442\u0435 \u0434\u0440\u0443\u0433\u043e\u0433\u043e \u043a\u0435\u0440\u0456\u0432\u043d\u0438\u043a\u0430 \u0437\u0430\u0440\u0430\u0437 \u2014 \u0456\u043d\u0448\u0438\u0439 \u0441\u0432\u0456\u0439 \u043f\u0440\u0438\u0441\u0442\u0440\u0456\u0439 \u0430\u0431\u043e \u043b\u044e\u0434\u0438\u043d\u0443, \u044f\u043a\u0456\u0439 \u0434\u043e\u0432\u0456\u0440\u044f\u0454\u0442\u0435.";
  this.aoo = "\u041a\u0435\u0440\u0456\u0432\u043d\u0438\u043a\u0438";
