  this.anw = "\u0421\u043a\u0456\u043b\u044c\u043a\u0438 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432 \u043d\u0430\u0437\u0432\u0430\u043b\u0438";
