  this.anr = "\u041a\u043b\u044e\u0447 \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u044e \u043d\u043e\u0432\u043e\u0433\u043e \u043a\u0435\u0440\u0456\u0432\u043d\u0438\u043a\u0430";
